    /**
     * Show all the invalid properties with reasons.
     *
     * @return array invalid properties with reasons
     */
    public function listInvalidProperties()
    {
        $invalidProperties = [];

        if (!is_null($this->container['postal_address']) && (mb_strlen($this->container['postal_address']) > 250)) {
            $invalidProperties[] = "invalid value for 'postal_address', the character length must be smaller than or equal to 250.";
        }

        if (!is_null($this->container['postal_code']) && (mb_strlen($this->container['postal_code']) > 5)) {
            $invalidProperties[] = "invalid value for 'postal_code', the character length must be smaller than or equal to 5.";
        }

        $allowedValues = $this->getProvinceAllowableValues();
        if (!is_null($this->container['province']) && !in_array($this->container['province'], $allowedValues, true)) {
            $invalidProperties[] = sprintf(
                "invalid value '%s' for 'province', must be one of '%s'",
                $this->container['province'],
                implode("', '", $allowedValues)
            );
        }

        if (!is_null($this->container['province']) && (mb_strlen($this->container['province']) > 50)) {
            $invalidProperties[] = "invalid value for 'province', the character length must be smaller than or equal to 50.";
        }

        $allowedValues = $this->getCountryAllowableValues();
        if (!is_null($this->container['country']) && !in_array($this->container['country'], $allowedValues, true)) {
            $invalidProperties[] = sprintf(
                "invalid value '%s' for 'country', must be one of '%s'",
                $this->container['country'],
                implode("', '", $allowedValues)
            );
        }

        if (!is_null($this->container['country']) && (mb_strlen($this->container['country']) > 2)) {
            $invalidProperties[] = "invalid value for 'country', the character length must be smaller than or equal to 2.";
        }

        if (!is_null($this->container['city']) && (mb_strlen($this->container['city']) > 50)) {
            $invalidProperties[] = "invalid value for 'city', the character length must be smaller than or equal to 50.";
        }

        return $invalidProperties;
    }

